def repeat_input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:
    embeddings = self.item_emb(seq)
    earlier_matches = torch.tril(
        seq.unsqueeze(2).eq(seq.unsqueeze(1)), diagonal=-1
    )
    counts = earlier_matches.sum(dim=-1).clamp(max=3).to(embeddings.dtype)
    repeat_strength = torch.log1p(counts) / math.log(4.0)
    scales = 1.0 + 0.1 * repeat_strength * seq.ne(0).to(embeddings.dtype)
    return embeddings * scales.unsqueeze(-1)

def encode(self, seq: torch.Tensor) -> torch.Tensor:
    emb = self.dropout(self.repeat_input_embeddings(seq))
